#include <SPI.h>
#include <FS.h>
#include <SD.h>
#include <TFT_eSPI.h>

// --- АППАРАТНЫЕ ПИНЫ ДЛЯ CHEAP YELLOW DISPLAY (CYD) ---
#define CYD_LED_BLUE 17
#define CYD_BUZZER 26
#define CYD_BLK 21

TFT_eSPI tft = TFT_eSPI();

// Параметры нашей нейросети (40 интентов)
int vocab_size = 0;
float* w1 = nullptr;
float* b1 = nullptr;
float* w2 = nullptr;
float* b2 = nullptr;
float* w3 = nullptr;
float* b3 = nullptr;

// Буферы для ввода текста с экранной клавиатуры
char user_input_buffer[64] = "";
int input_ptr = 0;

void init_hardware() {
    pinMode(CYD_LED_BLUE, OUTPUT);
    pinMode(CYD_BUZZER, OUTPUT);
    pinMode(CYD_BLK, OUTPUT);
    digitalWrite(CYD_BLK, HIGH); // Включаем подсветку экрана

    tft.init();
    tft.setRotation(1); // Альбомный режим (320x240)
    tft.fillScreen(TFT_BLACK);

    Serial.begin(115200);
}

void draw_ui_skeleton() {
    tft.fillRect(0, 0, 320, 30, TFT_DARKGREEN);
    tft.setTextColor(TFT_WHITE);
    tft.setTextSize(1);
    tft.drawString("ECHOVE CHAT OS v0.6", 10, 8);

    // Окно вывода диалога
    tft.drawRect(5, 35, 310, 110, TFT_GREEN);
    tft.fillRect(6, 36, 308, 108, TFT_BLACK);

    // Строка ввода текста
    tft.drawRect(5, 150, 310, 25, TFT_WHITE);
    tft.fillRect(6, 151, 308, 23, TFT_BLACK);
}
bool load_weights_from_sd() {
    if (!SD.begin(5)) { // 5 - стандартный CS пин SD-карты на CYD
        tft.drawString("SD CARD ERROR!", 10, 50);
        return false;
    }
    File f = SD.open("/weights.bin", FILE_READ);
    if (!f) {
        tft.drawString("WEIGHTS.BIN NOT FOUND!", 10, 50);
        return false;
    }
    // Читаем Слой 1 (выделяем память динамически)
    uint32_t len = 0; f.read((uint8_t*)&len, 4);
    w1 = new float[len]; f.read((uint8_t*)w1, len * 4);
    f.read((uint8_t*)&len, 4);
    b1 = new float[len]; f.read((uint8_t*)b1, len * 4);
    // Читаем Слой 2
    f.read((uint8_t*)&len, 4);
    w2 = new float[len]; f.read((uint8_t*)w2, len * 4);
    f.read((uint8_t*)&len, 4);
    b2 = new float[len]; f.read((uint8_t*)b2, len * 4);
    // Читаем Слой 3
    f.read((uint8_t*)&len, 4);
    w3 = new float[len]; f.read((uint8_t*)w3, len * 4);
    f.read((uint8_t*)&len, 4);
    b3 = new float[len]; f.read((uint8_t*)b3, len * 4);
    f.close();
    return true;
}

int ask_echove_cpp(const char* input_text) {
    // Простейший инференс на C++: умножение матриц прямо из массивов
    // Напрямую выдает ID интента без нагрузки на RAM благодаря указателям
    float hidden1[256] = {0};
    for(int i=0; i<256; i++) {
        hidden1[i] = b1[i];
        // Имитируем Bag of Words по ключевым словам словаря
        if(strstr(input_text, "привет")) hidden1[i] += w1[i * 100 + 0]; 
        if(strstr(input_text, "попищи")) hidden1[i] += w1[i * 100 + 1];
        if(hidden1[i] < 0) hidden1[i] = 0; // ReLU
    }
    float hidden2[256] = {0};
    for(int i=0; i<256; i++) {
        hidden2[i] = b2[i];
        for(int j=0; j<256; j++) hidden2[i] += hidden1[j] * w2[i * 256 + j];
        if(hidden2[i] < 0) hidden2[i] = 0; // ReLU
    }
    float logits[40] = {0};
    int max_id = 0;
    for(int i=0; i<40; i++) {
        logits[i] = b3[i];
        for(int j=0; j<256; j++) logits[i] += hidden2[j] * w3[i * 256 + j];
        if(logits[i] > logits[max_id]) max_id = i;
    }
    return max_id;
}

void execute_hw_action_cpp(int intent_id) {
    if (intent_id == 11) digitalWrite(CYD_BLK, LOW);  // Выключить экран
    else if (intent_id == 10) digitalWrite(CYD_BLK, HIGH); // Включить экран
    else if (intent_id == 15) { // Попищи
        for(int i=0; i<3; i++) {
            digitalWrite(CYD_BUZZER, HIGH); delay(80);
            digitalWrite(CYD_BUZZER, LOW); delay(50);
        }
    }
    else if (intent_id == 19) { // Reboot
        digitalWrite(CYD_BUZZER, HIGH); delay(400);
        digitalWrite(CYD_BUZZER, LOW);
        ESP.restart(); // Жесткий перезапуск чипа силами SDK!
    }
}
// --- ОТРИСОВКА СЕНСОРНОЙ КЛАВИАТУРЫ И КООРДИНАТНЫЙ ХАНДЛЕР ---
const char kb_map[3][10] = {
    {'Q','W','E','R','T','Y','U','I','O','P'},
    {'A','S','D','F','G','H','J','K','L','_'},
    {'Z','X','C','V','B','N','M',' ','<','='} // < - бэкспейс, = - Enter
};

void draw_keyboard() {
    tft.setTextSize(1);
    tft.setTextColor(TFT_GREEN);
    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 10; c++) {
            int x = 5 + c * 31;
            int y = 180 + r * 20;
            tft.drawRect(x, y, 29, 18, TFT_DARKGREEN);
            tft.drawChar(kb_map[r][c], x + 10, y + 5, 1);
        }
    }
}

// Стандартная база шаблонов ответов на C++
const char* get_template_cpp(int id) {
    switch(id) {
        case 0:  return "Echove: Салют, создатель! Я на связи.";
        case 1:  return "Echove: Я модель Echove Forwarder 100K C++.";
        case 2:  return "Echove: Конец связи! Отключаю потоки. Бб!";
        case 3:  return "Echove: Всегда пожалуйста! Рада помочь.";
        case 10: return "Echove: Принято! Включаю дисплей CYD.";
        case 11: return "Echove: Выполняю. Гашу подсветку экрана TFT.";
        case 15: return "Echove: Пиииип! Звуковой бузер платы активен!";
        case 19: return "Echove: Внимание! Выполняю рестарт чипа!";
        case 20: return "Echove: Рисую котика:  /\\_/\\  (o.o)  >^<";
        case 21: return "Echove: Рисую меч:  /| █▒▒░░░░░░░░░░░>";
        case 30: return "Echove: Сам такой! Мои веса обиделись. 😤";
        case 34: return "Echove: Эх, были бы руки - сварила бы кофе...";
        default: return "Echove: Промпт не распознан. Измени фразу!";
    }
}

void process_touch() {
    uint16_t t_x = 0, t_y = 0;
    // Опрашиваем тач CYD через встроенные либы TFT_eSPI
    if (tft.getTouch(&t_x, &t_y)) {
        // Проверяем, попал ли палец на зону клавиатуры
        if (t_y >= 180 && t_y <= 240 && t_x >= 5 && t_x <= 315) {
            int c = (t_x - 5) / 31;
            int r = (t_y - 180) / 20;
            if (c >= 0 && c < 10 && r >= 0 && r < 3) {
                char key = kb_map[r][c];

                if (key == '<') { // Бэкспейс
                    if (input_ptr > 0) user_input_buffer[--input_ptr] = '\0';
                }
                else if (key == '=') { // ENTER - отправка в ИИ!
                    if (input_ptr > 0) {
                        tft.fillRect(6, 36, 308, 108, TFT_BLACK); // Чистим окно чата
                        tft.setTextColor(TFT_WHITE);
                        tft.drawString(user_input_buffer, 10, 45); // Выводим промпт

                        // Считаем нейросеть прямо силами C++!
                        int intent_id = ask_echove_cpp(user_input_buffer);

                        tft.setTextColor(TFT_GREEN);
                        tft.drawString(get_template_cpp(intent_id), 10, 80); // Выводим ответ

                        execute_hw_action_cpp(intent_id); // Крутим пины

                        // Чистим буфер ввода
                        memset(user_input_buffer, 0, sizeof(user_input_buffer));
                        input_ptr = 0;
                    }
                }
                else { // Обычная буква
                    if (input_ptr < 49) {
                        user_input_buffer[input_ptr++] = key;
                        user_input_buffer[input_ptr] = '\0';
                    }
                }

                // Перерисовываем строку ввода на экране
                tft.fillRect(6, 151, 308, 23, TFT_BLACK);
                tft.setTextColor(TFT_WHITE);
                tft.drawString(user_input_buffer, 10, 158);
                delay(200); // Анти-дребезг тачскрина
            }
        }
    }
}

// --- СТАНДАРТНЫЙ ЦИКЛ ARDUINO CORE ---
void setup() {
    init_hardware();
    draw_ui_skeleton();

    tft.setTextColor(TFT_YELLOW);
    tft.drawString("Mounting SD & Loading AI weights...", 10, 50);

    if (load_weights_from_sd()) {
        tft.fillRect(6, 36, 308, 108, TFT_BLACK);
        tft.setTextColor(TFT_GREEN);
        tft.drawString("Echove: OS ready! Type using touchscreen.", 10, 45);
        draw_keyboard();
    }
}

void loop() {
    process_touch();
}
